// ── Validate & Prepare Context ──────────────────────────────
const input = $input.first().json.body;

const evidenceContext = {
  user_question: input.query || 'No query provided',
  analysis_type: input.analysis_plan?.analysis_type || input.method || 'unknown',
  aoi: input.aoi_bbox || [],
  event_date: input.event_date || null,
  statistics: input.statistics || {},
  change_map_summary: input.change_map_summary || {},
  selected_scenes: (input.selected_scenes || []).map(s => ({
    id: s.item_id || s.id,
    sensor: s.sensor || 'unknown',
    role: s.role || 'unknown',
    datetime: s.datetime || 'unknown',
  })),
  method: input.method || 'unknown',
  confidence: input.confidence || 'unknown',
  limitations: input.limitations || [],
  processing_steps: input.processing_steps || [],
  evidence: input.evidence || {},
  analysis_id: input.analysis_id || 'unknown',
};

return [{ json: evidenceContext }];

// ── Validate LLM output ─────────────────────────────────────
const llmOutput = $input.first().json;
const ctx = $('Validate & Prepare Context').first().json;

let explanation;
try {
  const content = llmOutput.choices?.[0]?.message?.content || llmOutput.text || JSON.stringify(llmOutput);
  explanation = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  return [{ json: { valid: false, reason: 'Invalid JSON: ' + e.message, raw_output: llmOutput, needs_human_review: true } }];
}

const required = ['summary', 'key_findings', 'confidence_statement', 'limitations'];
const missing = required.filter(f => !explanation[f]);
if (missing.length > 0) {
  return [{ json: { valid: false, reason: 'Missing: ' + missing.join(', '), raw_output: explanation, needs_human_review: true } }];
}

if (!Array.isArray(explanation.key_findings)) {
  return [{ json: { valid: false, reason: 'key_findings must be array', raw_output: explanation, needs_human_review: true } }];
}

return [{ json: { valid: true, explanation, needs_human_review: false } }];

// ── Check severity → route to human review if HIGH/CRITICAL ──
const input = $input.first().json;
const ctx = $('Validate & Prepare Context').first().json;
const severity = input.explanation?.severity || 'MEDIUM';

const report = {
  analysis_id: ctx.analysis_id,
  generated_at: new Date().toISOString(),
  summary: input.explanation.summary,
  key_findings: input.explanation.key_findings || [],
  affected_area: input.explanation.affected_area || ctx.change_map_summary,
  spatial_findings: input.explanation.spatial_findings || {},
  confidence_statement: input.explanation.confidence_statement,
  limitations: input.explanation.limitations || ctx.limitations,
  evidence_references: input.explanation.evidence_references || [],
  scenes_used: ctx.selected_scenes,
  method: ctx.method,
  computed_statistics: ctx.statistics,
  severity: severity,
  human_review: false,
};

// HIGH/CRITICAL severity → require human review
const needsReview = (severity === 'HIGH' || severity === 'CRITICAL');

return [{ json: { ...report, needs_human_review: needsReview } }];

// ── Prepare Human Review Package ─────────────────────────────
const report = $input.first().json;

const reviewPackage = {
  ...report,
  human_review: true,
  review_status: 'pending',
  review_url: `http://localhost:3000/review/${report.analysis_id}`,
  review_instructions: 'Review the analysis explanation below. Approve to publish, or reject with comments.',
};

return [{ json: reviewPackage }];

// ── Process Human Decision ──────────────────────────────────
const formSubmission = $input.first().json;
const originalReport = $('Prepare Review Package').first().json;

const decision = formSubmission['Reviewer Decision'] || '';
const comments = formSubmission['Reviewer Comments'] || '';

let status, finalReport;

if (decision.startsWith('Approve')) {
  status = 'approved';
  finalReport = {
    ...originalReport,
    human_review: true,
    review_status: 'approved',
    reviewer_comments: comments,
    reviewed_at: new Date().toISOString(),
    published: true,
    published_at: new Date().toISOString(),
  };
} else if (decision.startsWith('Reject')) {
  status = 'rejected';
  finalReport = {
    ...originalReport,
    human_review: true,
    review_status: 'rejected',
    reviewer_comments: comments,
    reviewed_at: new Date().toISOString(),
    published: false,
  };
} else {
  status = 'approved_with_edits';
  finalReport = {
    ...originalReport,
    human_review: true,
    review_status: 'approved_with_edits',
    reviewer_comments: comments,
    reviewed_at: new Date().toISOString(),
    published: true,
    published_at: new Date().toISOString(),
  };
}

return [{ json: finalReport }];

// ── Human Review Package (Validation Failed) ────────────────
const input = $input.first().json;
const ctx = $('Validate & Prepare Context').first().json;

const reviewPackage = {
  analysis_id: ctx.analysis_id,
  generated_at: new Date().toISOString(),
  human_review: true,
  review_status: 'pending_validation_failure',
  review_reason: input.reason || 'Validation failed',
  raw_llm_output: input.raw_output,
  evidence_context: ctx,
  summary: 'This analysis result requires human review before publication.',
  key_findings: [{ finding: 'Automated explanation validation failed', evidence_id: ctx.analysis_id, confidence: 'requires_review' }],
  confidence_statement: 'Pending human review',
  limitations: [...(ctx.limitations || []), 'Validation failed: ' + (input.reason || 'unknown')],
};

return [{ json: reviewPackage }];
